    public static function public_key_pem() {
        return trim(self::PUBLIC_KEY_PEM) . "\n";
    }

    public static function is_configured() {
        return self::encryption_key_bin() !== ''
            && strpos(self::PUBLIC_KEY_PEM, 'REPLACE_ME') === false;
